//#region src/plugins/navigation.ts
function registerNavigationPlugin(server, deps) {
	const { adbService, deviceContext, stateSnapshotService, coordinateService } = deps;
	server.registerTool("open_url", {
		title: "Open URL",
		description: `Open a URL in the device's default browser or a deep-link handler. Supports http://, https://, and custom URI schemes (e.g. myapp://path).

Use for launching web pages, deep-linking into apps, or testing URL-based navigation flows.`,
		inputSchema: {
			url: string().describe("URL to open. Supports http://, https://, and custom URI schemes."),
			settle: number().int().min(0).max(5e3).optional().describe("Wait ms after action for UI to settle. Default: 0. Pass 800-1500 after URL navigation (page load may be slow)."),
			serial: string().optional().describe("Device serial number. If omitted, uses the default device.")
		},
		annotations: { destructiveHint: true }
	}, withErrorHandling("Open URL", async ({ url, settle, serial }) => {
		const s = await deviceContext.resolveDevice(serial);
		const escaped = escapeUrlForAm(url);
		await adbService.safeShell(s, `am start -a android.intent.action.VIEW --uri '${escaped}'`);
		stateSnapshotService.invalidate(s);
		await settleDelay(settle);
		return { content: [{
			type: "text",
			text: `Opened URL: ${url}`
		}] };
	}));
	server.registerTool("get_orientation", {
		title: "Get Orientation",
		description: "Get the current screen orientation of the device. Returns the actual display orientation (via dumpsys display), user rotation setting, and auto-rotation state.",
		inputSchema: { serial: string().optional().describe("Device serial number. If omitted, uses the default device.") },
		annotations: { readOnlyHint: true }
	}, withErrorHandling("Get orientation", async ({ serial }) => {
		const s = await deviceContext.resolveDevice(serial);
		const state = await adbService.getOrientationState(s);
		const label = [
			"portrait",
			"landscape",
			"reverse-portrait",
			"reverse-landscape"
		][state.orientation] ?? `unknown (${state.orientation})`;
		return { content: [{
			type: "text",
			text: JSON.stringify({
				orientation: state.orientation,
				label,
				userRotation: state.userRotation,
				autoRotation: state.autoRotation
			}, null, 2)
		}] };
	}));
	server.registerTool("set_orientation", {
		title: "Set Orientation",
		description: `Set the device screen orientation. Disables auto-rotation first, then locks to the specified orientation.

Values: portrait (0), landscape (1), reverse-portrait (2), reverse-landscape (3).
Use "auto" to re-enable auto-rotation.`,
		inputSchema: {
			orientation: _enum([
				"portrait",
				"landscape",
				"reverse-portrait",
				"reverse-landscape",
				"auto"
			]).describe("Target orientation. \"auto\" re-enables auto-rotation."),
			settle: number().int().min(0).max(5e3).optional().describe("Wait ms after action for UI to settle. Default: 0. Pass 500-1000 after orientation change (system animation needs time)."),
			serial: string().optional().describe("Device serial number. If omitted, uses the default device.")
		},
		annotations: { destructiveHint: true }
	}, withErrorHandling("Set orientation", async ({ orientation, settle, serial }) => {
		const s = await deviceContext.resolveDevice(serial);
		if (orientation === "auto") {
			await adbService.setOrientation(s, { autoRotation: true });
			stateSnapshotService.invalidate(s);
			coordinateService.invalidateCache(s);
			return { content: [{
				type: "text",
				text: "Enabled auto-rotation."
			}] };
		}
		const value = {
			"portrait": 0,
			"landscape": 1,
			"reverse-portrait": 2,
			"reverse-landscape": 3
		}[orientation];
		await adbService.setOrientation(s, {
			autoRotation: false,
			userRotation: value
		});
		stateSnapshotService.invalidate(s);
		coordinateService.invalidateCache(s);
		await settleDelay(settle);
		return { content: [{
			type: "text",
			text: `Changed orientation to ${orientation} (${value}).`
		}] };
	}));
}
