//#region src/lib/ui-parser.ts
/**
* Format a raw ScreenElement for LLM consumption.
* Strips empty strings to undefined and applies field renaming
* (label → contentDesc, identifier → resourceId) for consistency
* with ui_find_element / ui_tap input parameter names.
*/
function formatElement(el) {
	return {
		type: el.type,
		text: el.text || void 0,
		contentDesc: el.contentDesc || void 0,
		resourceId: el.resourceId || void 0,
		className: el.className,
		bounds: el.bounds,
		centerX: el.centerX,
		centerY: el.centerY,
		clickable: el.clickable || void 0,
		scrollable: el.scrollable || void 0,
		longClickable: el.longClickable || void 0,
		focused: el.focused || void 0,
		enabled: el.enabled === false ? false : void 0,
		checked: el.checked || void 0,
		selected: el.selected || void 0
	};
}
/** Interactive class suffixes — elements worth reporting to the LLM. */
const INTERACTIVE_SUFFIXES = [
	"Button",
	"EditText",
	"TextView",
	"ImageView",
	"CheckBox",
	"RadioButton",
	"Switch",
	"ToggleButton",
	"Spinner",
	"SeekBar",
	"ProgressBar",
	"ImageButton",
	"Image",
	"SearchField",
	"Icon",
	"StaticText",
	"TextField",
	"MenuItem",
	"Tab",
	"ListItem",
	"CheckedTextView",
	"ScrollView",
	"RecyclerView",
	"ListView",
	"ViewPager",
	"WebView"
];
/**
* Derive a short semantic type from an Android class name.
*
* "android.widget.Button"        → "Button"
* "android.widget.TextView"      → "TextView"
* "com.example.CustomWidget"     → "CustomWidget"
* ""                              → "Unknown"
*/
function inferType(className) {
	if (!className) return "Unknown";
	const parts = className.split(".");
	return parts[parts.length - 1] || "Unknown";
}
/** Check if a class name looks like an interactive element. */
function isInteractive(className) {
	if (!className) return false;
	const short = inferType(className);
	return INTERACTIVE_SUFFIXES.some((s) => short.includes(s));
}
/**
* Parse a UIAutomator bounds string `[x1,y1][x2,y2]` into a Bounds object.
* Returns null if the string doesn't match.
*/
function parseBounds(raw) {
	const match = raw.match(/\[(\d+),(\d+)\]\[(\d+),(\d+)\]/);
	if (!match) return null;
	const left = Number.parseInt(match[1], 10);
	const top = Number.parseInt(match[2], 10);
	const right = Number.parseInt(match[3], 10);
	const bottom = Number.parseInt(match[4], 10);
	const width = right - left;
	const height = bottom - top;
	if (width <= 0 || height <= 0) return null;
	return {
		x: left,
		y: top,
		width,
		height
	};
}
/** Extract a named attribute from an XML node's attribute string. */
function getAttr(attrString, name) {
	const escaped = name.replaceAll("-", "\\-");
	const m = attrString.match(new RegExp(`${escaped}="([^"]*)"`));
	return m ? m[1] : "";
}
/**
* Parse a UIAutomator XML dump into a flat list of ScreenElements.
*
* - Walks all `<node>` tags (both self-closing and opening).
* - Filters to interactive elements (buttons, text fields, etc.).
* - Excludes elements with zero-size bounds.
* - Sorts output top-to-bottom, left-to-right for deterministic ordering.
*/
function parseUiTree(xml) {
	const elements = [];
	const nodeRegex = /<node\s+([^>]*?)(?:\/>|>)/g;
	let match;
	while ((match = nodeRegex.exec(xml)) !== null) {
		const attrs = match[1];
		const className = getAttr(attrs, "class");
		const isClickable = getAttr(attrs, "clickable") === "true";
		if (!isInteractive(className) && !isClickable) continue;
		const bounds = parseBounds(getAttr(attrs, "bounds"));
		if (!bounds) continue;
		const text = getAttr(attrs, "text");
		const contentDesc = getAttr(attrs, "content-desc");
		const resourceId = getAttr(attrs, "resource-id");
		const isPassword = getAttr(attrs, "password") === "true";
		if (!text && !contentDesc && !resourceId) continue;
		elements.push({
			type: inferType(className),
			text: isPassword ? "[password field]" : text,
			contentDesc,
			resourceId,
			className,
			bounds,
			centerX: Math.round(bounds.x + bounds.width / 2),
			centerY: Math.round(bounds.y + bounds.height / 2),
			clickable: getAttr(attrs, "clickable") === "true",
			scrollable: getAttr(attrs, "scrollable") === "true",
			longClickable: getAttr(attrs, "long-clickable") === "true",
			focused: getAttr(attrs, "focused") === "true",
			enabled: getAttr(attrs, "enabled") !== "false",
			checked: getAttr(attrs, "checked") === "true",
			selected: getAttr(attrs, "selected") === "true"
		});
	}
	elements.sort((a, b) => {
		const dy = a.bounds.y - b.bounds.y;
		if (Math.abs(dy) > 10) return dy;
		return a.bounds.x - b.bounds.x;
	});
	return elements;
}
/**
* Filter a list of ScreenElements by query criteria.
* All provided criteria are AND-combined.
*
* @param opts.exact_match - When true, text/class_name/content_desc use
*   strict equality instead of substring match. resource_id is always exact.
*/
function filterElements(elements, query, opts) {
	let result = elements;
	const exact = opts?.exact_match === true;
	if (query.text) {
		const lower = query.text.toLowerCase();
		result = exact ? result.filter((el) => el.text.toLowerCase() === lower) : result.filter((el) => el.text.toLowerCase().includes(lower));
	}
	if (query.resource_id) result = result.filter((el) => el.resourceId === query.resource_id);
	if (query.class_name) result = exact ? result.filter((el) => el.className === query.class_name) : result.filter((el) => el.className.includes(query.class_name));
	if (query.content_desc) {
		const lower = query.content_desc.toLowerCase();
		result = exact ? result.filter((el) => el.contentDesc.toLowerCase() === lower) : result.filter((el) => el.contentDesc.toLowerCase().includes(lower));
	}
	return result;
}
