//#region src/plugins/perception.ts
function registerPerceptionPlugin(server, deps) {
	const { deviceContext, stateSnapshotService, adbService, screenshotService, coordinateService } = deps;
	server.registerTool("get_screen_state", {
		title: "Get Screen State",
		description: `Get a unified snapshot of the current screen: foreground app, screen dimensions, and all interactive UI elements. Returns a snapshot_id that can be passed to ui_tap and ui_find_element to reuse cached UI state (avoids re-dumping).

Set include_screenshot=true to also receive a visual capture in the same call — use this when you need both the element tree and the visual appearance (one round trip instead of two).`,
		inputSchema: {
			include_screenshot: boolean().optional().describe("Also capture a screenshot in the same call. Default: false."),
			serial: string().optional().describe("Device serial number. If omitted, uses the default device.")
		},
		annotations: { readOnlyHint: true }
	}, withErrorHandling("Get screen state", async ({ include_screenshot, serial }) => {
		const s = await deviceContext.resolveDevice(serial);
		const [snapshot, app, screenSize, shot] = await Promise.all([
			stateSnapshotService.create(s),
			(async () => {
				const { uiService } = deps;
				return uiService.getForegroundApp(s);
			})(),
			adbService.getScreenSize(s),
			include_screenshot ? screenshotService.capture(s) : Promise.resolve(null)
		]);
		if (shot) coordinateService.update(s, shot.deviceWidth, shot.deviceHeight);
		const state = {
			snapshotId: snapshot.id,
			app,
			screen: {
				width: screenSize.width,
				height: screenSize.height
			},
			elementCount: snapshot.elements.length,
			elements: snapshot.elements.map(formatElement),
			timestamp: snapshot.timestamp,
			age: Math.round((Date.now() - snapshot.timestamp) / 1e3),
			fresh: Date.now() - snapshot.timestamp < 1e4
		};
		const content = [];
		if (shot) content.push({
			type: "image",
			data: shot.base64,
			mimeType: shot.mimeType
		});
		content.push({
			type: "text",
			text: JSON.stringify(shot ? {
				...state,
				image: {
					width: shot.width,
					height: shot.height,
					source: shot.source
				}
			} : state, null, 2)
		});
		return { content };
	}));
	server.registerTool("get_foreground_app", {
		title: "Get Foreground App",
		description: "Get the package name and activity of the currently visible app. Lightweight query, no UI dump.",
		inputSchema: { serial: string().optional().describe("Device serial number. If omitted, uses the default device.") },
		annotations: { readOnlyHint: true }
	}, withErrorHandling("Get foreground app", async ({ serial }) => {
		const s = await deviceContext.resolveDevice(serial);
		const { uiService } = deps;
		const app = await uiService.getForegroundApp(s);
		return { content: [{
			type: "text",
			text: JSON.stringify(app, null, 2)
		}] };
	}));
}
//#endregion
