function registerScreenshotPlugin(server, deps) {
	const { screenshotService, deviceContext, coordinateService } = deps;
	server.registerTool("screenshot", {
		title: "Screenshot",
		description: `Capture the current screen as a JPEG image.

The image may be resized for efficiency. The returned metadata includes both
image dimensions and device dimensions. All positional coordinates (tap, swipe,
etc.) are percentages (0.0–1.0) — the system converts to device pixels automatically.`,
		inputSchema: { serial: string().optional().describe("Device serial number. If omitted, uses the default device.") }
	}, withErrorHandling("Screenshot", async ({ serial }) => {
		const s = await deviceContext.resolveDevice(serial);
		const result = await screenshotService.capture(s);
		coordinateService.update(s, result.deviceWidth, result.deviceHeight);
		return { content: [{
			type: "image",
			data: result.base64,
			mimeType: result.mimeType
		}, {
			type: "text",
			text: JSON.stringify({
				size: {
					width: result.width,
					height: result.height
				},
				deviceSize: {
					width: result.deviceWidth,
					height: result.deviceHeight
				},
				source: result.source
			})
		}] };
	}));
}
