const MAX_OUTPUT_LENGTH = 1e4;
function registerShellPlugin(server, deps) {
	const { adbService, deviceContext } = deps;
	server.registerTool("shell_exec", {
		title: "Shell Execute",
		description: "Execute a shell command on the Android device via ADB. Returns stdout (truncated to 10KB for large outputs). Use for commands not covered by other tools: `dumpsys`, `getprop`, `settings`, `content`, `pm`, `am`, etc. Avoid commands that require interactive input or produce binary output.",
		inputSchema: {
			command: string().describe("Shell command to execute on the device (e.g. \"dumpsys activity top\", \"settings get system screen_brightness\")"),
			serial: string().optional().describe("Device serial number. If omitted, uses the default device.")
		}
	}, withErrorHandling("Shell command", async ({ command, serial }) => {
		const s = await deviceContext.resolveDevice(serial);
		const output = await adbService.safeShell(s, command);
		return { content: [{
			type: "text",
			text: output.length > MAX_OUTPUT_LENGTH ? `${output.slice(0, MAX_OUTPUT_LENGTH)}\n... (truncated: showing first ${MAX_OUTPUT_LENGTH} of ${output.length} characters — refine the command, e.g. add grep/tail, to see more)` : output
		}] };
	}));
}
