/** Max candidate elements included in failure diagnostics. */
const MAX_CANDIDATES = 15;
/**
* Compact element summary for failure diagnostics — gives the agent enough
* context to correct its query without another observation round trip.
*/
function summarizeElements(elements) {
	return elements.slice(0, MAX_CANDIDATES).map((el) => ({
		type: el.type,
		text: el.text || void 0,
		contentDesc: el.contentDesc || void 0,
		resourceId: el.resourceId || void 0,
		centerX: el.centerX,
		centerY: el.centerY
	}));
}
function registerUiPlugin(server, deps) {
	const { deviceContext, inputService, stateSnapshotService } = deps;
	server.registerTool("ui_dump", {
		title: "UI Dump",
		description: "Dump the current UI accessibility hierarchy. Returns raw XML by default, or structured JSON. Both formats register a snapshot reusable by ui_tap / ui_find_element.",
		inputSchema: {
			format: _enum(["xml", "json"]).optional().describe("Output format. \"xml\" (default) returns raw uiautomator XML. \"json\" returns parsed ScreenElement array."),
			serial: string().optional().describe("Device serial number. If omitted, uses the default device.")
		},
		annotations: { readOnlyHint: true }
	}, withErrorHandling("Dump UI", async ({ format, serial }) => {
		const s = await deviceContext.resolveDevice(serial);
		if (format === "json") {
			const snapshot = await stateSnapshotService.create(s);
			return { content: [{
				type: "text",
				text: JSON.stringify({
					count: snapshot.elements.length,
					snapshotId: snapshot.id,
					elements: snapshot.elements.map(formatElement)
				}, null, 2)
			}] };
		}
		const { uiService } = deps;
		const xml = await uiService.dumpXml(s);
		const snapshot = stateSnapshotService.store(s, parseUiTree(xml));
		return { content: [{
			type: "text",
			text: `${xml}\n<!-- snapshotId: ${snapshot.id} (${snapshot.elements.length} interactive elements) — pass to ui_tap / ui_find_element to reuse this state -->`
		}] };
	}));
	server.registerTool("ui_find_element", {
		title: "Find UI Element",
		description: "Search the current UI hierarchy for elements matching criteria (text, resource ID, class name, or content description).",
		inputSchema: {
			text: string().optional().describe("Text content to search for (case-insensitive partial match)"),
			resource_id: string().optional().describe("Android resource ID to match exactly (e.g. \"com.example:id/button\")"),
			class_name: string().optional().describe("View class name to match (partial, e.g. \"Button\", \"EditText\")"),
			content_desc: string().optional().describe("Content description (accessibility label) to search for (case-insensitive partial match)"),
			exact_match: boolean().optional().describe("If true, require exact text/class_name/content_desc match instead of partial match. Default: false."),
			snapshot_id: string().optional().describe("Snapshot ID from get_screen_state. Uses cached UI state instead of re-dumping."),
			serial: string().optional().describe("Device serial number. If omitted, uses the default device.")
		},
		annotations: { readOnlyHint: true }
	}, withErrorHandling("Find UI elements", async ({ text, resource_id, class_name, content_desc, exact_match, snapshot_id, serial }) => {
		const s = await deviceContext.resolveDevice(serial);
		const { elements, fromSnapshot, snapshotId, snapshotExpired } = await stateSnapshotService.findElements(s, {
			text,
			resource_id,
			class_name,
			content_desc
		}, snapshot_id, { exact_match });
		return { content: [{
			type: "text",
			text: JSON.stringify({
				count: elements.length,
				snapshotId,
				fromCache: fromSnapshot,
				snapshotExpired: snapshotExpired || void 0,
				elements: elements.map(formatElement)
			}, null, 2)
		}] };
	}));
	server.registerTool("ui_tap", {
		title: "UI Tap Element",
		description: `Find a UI element and tap it in a single atomic operation. No screenshot or coordinates needed.

Uses device-native coordinates from uiautomator. Accepts text, resource_id, class_name, or content_desc selectors.

If snapshot_id is expired, the system automatically refreshes the UI state. Pass snapshot_id from get_screen_state to reuse cached state.`,
		inputSchema: {
			text: string().optional().describe("Text content to search for (case-insensitive partial match)"),
			resource_id: string().optional().describe("Android resource ID to match exactly (e.g. \"com.example:id/button\")"),
			class_name: string().optional().describe("View class name to match (partial, e.g. \"Button\", \"EditText\")"),
			content_desc: string().optional().describe("Content description (accessibility label) to search for (case-insensitive partial match)"),
			exact_match: boolean().optional().describe("If true, require exact text/class_name/content_desc match instead of partial match. Default: false."),
			index: number().int().nonnegative().optional().describe("Which match to tap if multiple elements match (0-based). Default: 0 (first match)."),
			snapshot_id: string().optional().describe("Snapshot ID from get_screen_state. Uses cached UI state instead of re-dumping."),
			settle: number().int().min(0).max(5e3).optional().describe("Wait ms after action for UI to settle. Default: 0. Pass 300-800 after page-changing actions."),
			serial: string().optional().describe("Device serial number. If omitted, uses the default device.")
		},
		annotations: { destructiveHint: true }
	}, withErrorHandling("UI tap", async ({ text, resource_id, class_name, content_desc, exact_match, index, snapshot_id, settle, serial }) => {
		const s = await deviceContext.resolveDevice(serial);
		const { elements, fromSnapshot, snapshotId, snapshotExpired } = await stateSnapshotService.findElements(s, {
			text,
			resource_id,
			class_name,
			content_desc
		}, snapshot_id, { exact_match });
		if (elements.length === 0) {
			const latest = stateSnapshotService.getLatest(s);
			return {
				content: [{
					type: "text",
					text: JSON.stringify({
						error: "No matching UI elements found.",
						query: {
							text,
							resource_id,
							class_name,
							content_desc,
							exact_match: exact_match || void 0
						},
						snapshotId,
						visibleElements: latest ? summarizeElements(latest.elements) : [],
						hint: "Check the query against visibleElements (spelling, resource id, or the element may be off-screen / require scrolling)."
					}, null, 2)
				}],
				isError: true
			};
		}
		const idx = index ?? 0;
		if (idx >= elements.length) return {
			content: [{
				type: "text",
				text: JSON.stringify({
					error: `Index ${idx} out of range.`,
					matchCount: elements.length,
					matches: summarizeElements(elements),
					hint: `Use index 0-${elements.length - 1}, or refine the query to disambiguate.`
				}, null, 2)
			}],
			isError: true
		};
		const target = elements[idx];
		const result = await inputService.track(s, () => inputService.tap(s, target.centerX, target.centerY));
		stateSnapshotService.invalidate(s);
		await settleDelay(settle);
		const matched = target.text || target.contentDesc || target.resourceId || target.className;
		const cacheInfo = fromSnapshot ? "cached" : "fresh dump";
		const expiredWarning = snapshotExpired ? " WARNING: requested snapshot_id was expired — used refreshed state." : "";
		return { content: [{
			type: "text",
			text: `Tapped "${matched}" (${target.type}) at (${target.centerX}, ${target.centerY}). Match ${idx + 1}/${elements.length} [${cacheInfo}, ${result.path} ${result.latencyMs}ms].${expiredWarning} Use get_screen_state to verify the UI changed.`
		}] };
	}));
	server.registerTool("ui_wait_for", {
		title: "Wait For UI Element",
		description: `Poll the UI hierarchy until an element matching the criteria appears, or until the timeout elapses. Use this after navigation actions (app_start, open_url, tap) instead of repeatedly calling ui_find_element — the retry loop runs server-side in a single tool call.

Returns JSON with found: true/false. When found, includes the matched element(s) and a snapshot_id usable by ui_tap. A found:false result is an expected outcome (not a tool failure) — inspect the screen with get_screen_state to see what actually happened.`,
		inputSchema: {
			text: string().optional().describe("Text content to wait for (case-insensitive partial match)"),
			resource_id: string().optional().describe("Android resource ID to match exactly (e.g. \"com.example:id/button\")"),
			class_name: string().optional().describe("View class name to match (partial, e.g. \"Button\", \"EditText\")"),
			content_desc: string().optional().describe("Content description (accessibility label) to wait for (case-insensitive partial match)"),
			exact_match: boolean().optional().describe("If true, require exact text/class_name/content_desc match instead of partial match. Default: false."),
			timeout_ms: number().int().min(1e3).max(6e4).optional().describe("Max time to wait in ms. Default: 10000."),
			poll_interval_ms: number().int().min(100).max(5e3).optional().describe("Interval between UI dumps in ms. Default: 500. Each poll performs a fresh UI dump."),
			serial: string().optional().describe("Device serial number. If omitted, uses the default device.")
		},
		annotations: { readOnlyHint: true }
	}, withErrorHandling("Wait for UI element", async ({ text, resource_id, class_name, content_desc, exact_match, timeout_ms, poll_interval_ms, serial }) => {
		if (!text && !resource_id && !class_name && !content_desc) return {
			content: [{
				type: "text",
				text: JSON.stringify({
					error: "At least one criterion is required.",
					hint: "Provide text, resource_id, class_name, or content_desc to specify what to wait for."
				}, null, 2)
			}],
			isError: true
		};
		const s = await deviceContext.resolveDevice(serial);
		const timeoutMs = timeout_ms ?? 1e4;
		const intervalMs = poll_interval_ms ?? 500;
		const start = Date.now();
		const deadline = start + timeoutMs;
		const query = {
			text,
			resource_id,
			class_name,
			content_desc
		};
		let polls = 0;
		for (;;) {
			polls++;
			const { elements, snapshotId } = await stateSnapshotService.findElements(s, query, void 0, { exact_match });
			if (elements.length > 0) return { content: [{
				type: "text",
				text: JSON.stringify({
					found: true,
					polls,
					elapsedMs: Date.now() - start,
					snapshotId,
					count: elements.length,
					elements: elements.map(formatElement)
				}, null, 2)
			}] };
			if (Date.now() + intervalMs > deadline) return { content: [{
				type: "text",
				text: JSON.stringify({
					found: false,
					polls,
					elapsedMs: Date.now() - start,
					timeoutMs,
					query: {
						...query,
						exact_match: exact_match || void 0
					},
					hint: "Element did not appear within the timeout. The screen may not have changed as expected — use get_screen_state (optionally with include_screenshot=true) to inspect the current UI."
				}, null, 2)
			}] };
			await sleep(intervalMs);
		}
	}));
}
