/** Register all MCP tool plugins. */
function registerAllPlugins(server, deps) {
	registerDevicePlugin(server, deps);
	registerScreenshotPlugin(server, deps);
	registerInputPlugin(server, deps);
	registerAppsPlugin(server, deps);
	registerClipboardPlugin(server, deps);
	registerShellPlugin(server, deps);
	registerFilesPlugin(server, deps);
	registerUiPlugin(server, deps);
	registerPerceptionPlugin(server, deps);
	registerNavigationPlugin(server, deps);
}
