	async install(serial, apkPath) {
		return withTimeout("app install", this.adbx.install(serial, apkPath), TRANSFER_TIMEOUT_MS);
	}
	/** Uninstall a package from the device. */
	async uninstall(serial, pkg) {
		return withTimeout("app uninstall", this.adbx.uninstall(serial, pkg), 6e4);
	}
