//#region src/lib/device-transform.ts
/**
* Compute the current visual frame dimensions.
*
* @param wmWidth  - width from `wm size` (fixed, never changes with rotation)
* @param wmHeight - height from `wm size` (fixed, never changes with rotation)
* @param orientation - mCurrentOrientation (0-3)
*/
function getDeviceVisual(wmWidth, wmHeight, orientation) {
	const isLandscape = orientation === 1 || orientation === 3;
	const minSide = Math.min(wmWidth, wmHeight);
	const maxSide = Math.max(wmWidth, wmHeight);
	return {
		orientation,
		visualWidth: isLandscape ? maxSide : minSide,
		visualHeight: isLandscape ? minSide : maxSide,
		isLandscape
	};
}
