//#region src/services/coordinate-service.ts
/** How long a cached entry is considered fresh (ms). */
const CACHE_TTL_MS = 3e4;
var CoordinateService = class {
	adbService;
	cache = /* @__PURE__ */ new Map();
	constructor(adbService) {
		this.adbService = adbService;
	}
	/**
	* Push visual dimensions after a screenshot capture.
	* This is the primary data path — no ADB query needed.
	*/
	update(serial, visualWidth, visualHeight) {
		const version = (this.cache.get(serial)?.version ?? 0) + 1;
		this.cache.set(serial, {
			visualWidth,
			visualHeight,
			version,
			updatedAt: Date.now()
		});
	}
	/**
	* Pure memory read — returns null if cache is empty (never queries ADB).
	*/
	getVisualSize(serial) {
		const entry = this.cache.get(serial);
		if (!entry) return null;
		return {
			visualWidth: entry.visualWidth,
			visualHeight: entry.visualHeight
		};
	}
	/**
	* Get the cache version number for a device (0 if no entry).
	* Used for debug output to confirm coordinate-system freshness.
	*/
	getVersion(serial) {
		return this.cache.get(serial)?.version ?? 0;
	}
	/**
	* Check whether the cached entry is still fresh (within TTL).
	*/
	isFresh(serial) {
		const entry = this.cache.get(serial);
		if (!entry) return false;
		return Date.now() - entry.updatedAt < CACHE_TTL_MS;
	}
	/**
	* Priority: cache → ADB fallback.
	*
	* Returns the visual size, querying ADB only if the cache is empty or stale.
	* After an ADB query, the result is written back to the cache.
	*/
	async ensureVisualSize(serial) {
		const cached = this.getVisualSize(serial);
		if (cached && this.isFresh(serial)) return cached;
		const display = await this.adbService.getDisplayState(serial);
		const visual = getDeviceVisual(display.width, display.height, display.orientation);
		const version = (this.cache.get(serial)?.version ?? 0) + 1;
		this.cache.set(serial, {
			visualWidth: visual.visualWidth,
			visualHeight: visual.visualHeight,
			version,
			updatedAt: Date.now()
		});
		return {
			visualWidth: visual.visualWidth,
			visualHeight: visual.visualHeight
		};
	}
	/**
	* Invalidate cache for a device (e.g. after orientation change).
	*/
	invalidateCache(serial) {
		this.cache.delete(serial);
	}
	/**
	* Invalidate all cached entries.
	*/
	invalidateAll() {
		this.cache.clear();
	}
};
